    let mut score = post_residual as f64;

    // 1. Base Strategy: Best Fit (minimize post_residual)
    // We prioritize keeping the residual small, but we weight it against bin fragmentation.

    // 2. Harmonic Penalty (Avoid creating "dead zones")
    // If post_residual is in the range (0, 10), it is likely too small to fit future items.
    // We penalize these "sliver" residuals heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 3. Lookahead Logic (Next Item Fit)
    // If the next item exists, prefer bins where the remaining space accommodates it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can perfectly or near-perfectly fit the next item.
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Penalize bins that cannot fit the next item if they are otherwise "tight".
            score += 15.0;
        }
    }

    // 4. Thresholding for New Bin vs. Existing Bin
    // If this is a new bin (bin_residual == bin_capacity):
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is already very low,
        // suggesting they are "clogged" and cannot accommodate future items.
        if mean_residual > 20.0 {
            score -= 30.0;
        } else {
            score += 50.0; // High penalty to discourage opening new bins prematurely.
        }
    }

    // 5. Fitting Context
    // If this is the only bin that can fit the item, we must take it (lower score).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 6. Progress Scaling
    // As we near the end of the stream, prioritize packing density over future flexibility.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
