        // Penalize if the current placement leaves a gap that is too small for common items
        if post_residual < 10 {
            score += 50.0;
        }
    }

    // 3. Fragmentation avoidance: Penalize creating bins with residuals far from the mean
    // This helps keep bins balanced in terms of remaining capacity.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.5;

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless no other 
    // bins can fit the item or the fitting bins are extremely poor matches.
    if bin_residual == bin_capacity {
