    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that cannot fit typical items (10-30 range)
    // If post_residual is small but > 0, it's often worse than 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Harmonic/Modulo alignment: Prefer leaving space that is a multiple of 20 
    // to accommodate common item distributions.
    score += ((post_residual % 20) as f64) * 0.5;

    // 3. Lookahead logic: If the next item fits into the current post_residual,
    // reward this bin heavily to maximize bin density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Fitting constraints: If this is the only bin that fits the current item,
    // we must take it unless the new-bin penalty is lower (handled by caller).
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // 5. Global state management: Penalize opening new bins when current mean_residual is high.
    // If we are opening a new bin (bin_residual == bin_capacity), increase cost if
    // current mean_residual suggests we have plenty of capacity elsewhere.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.4;
        // Discourage opening new bins too early in the stream
        score += (1.0 - (step_index as f64 / total_items as f64)) * 5.0;
    }

    // 6. Prefer bins that are already "tight" (low post_residual) to keep others empty.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

