pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (post_residual < 10) that are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Class Logic: Reward placements that leave a residual which is a multiple of common item sizes (e.g., 20, 25, 33).
    // This helps align residuals with potential future items.
    let harmonic_penalty = (post_residual % 20) as f64 * 1.5;
    score += harmonic_penalty;

    // 3. Lookahead logic: If the next item fits into the post_residual, prioritize this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. If this is the last chance for this item (fitting_bins_count == 1), penalize opening a new bin
    // unless the current fit is extremely poor (post_residual < 10).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global efficiency: If we are early in the stream, favor tighter packing (lower post_residual).
    // As the stream progresses, prioritize using existing bins to prevent fragmentation.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 - progress) * 2.0;

    // 6. Bias against opening new bins unless necessary.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "dead space" that cannot fit common small items (e.g., < 20).
    // If post_residual is in the "danger zone" (1..19), we penalize it heavily.
    if post_residual > 0 && post_residual < 20 {
        score += 50.0 + (20.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, reward this placement.
    // This is a form of Best-Fit-Lookahead.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // Harmonic weighting: Penalize bins that deviate from the mean residual of the set.
    // This encourages keeping bins at similar fullness levels (Best-Fit-like behavior).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // Threshold management: If this is the only bin that fits the current item, 
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // New-bin logic: If this is a new bin, apply a heavy penalty unless the average 
    // residual is already quite low (meaning existing bins are nearly full).
    if bin_residual == bin_capacity {
        score += 40.0 + (mean_residual * 0.5);
    }

    // Progression scaling: As we reach the end of the stream, prioritize closing bins
    // by tightening the penalty on small residuals.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}
